import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 321;

const COLORS = {
  accent: "#FF6B35",
  accentSoft: "rgba(255,107,53,0.12)",
  white: "#FFFFFF",
  whiteSubtle: "rgba(255,255,255,0.55)",
  whiteFaint: "rgba(255,255,255,0.08)",
  wrong: "#EF4444",
  wrongSoft: "rgba(239,68,68,0.10)",
  wrongBorder: "rgba(239,68,68,0.25)",
  right: "#4ADE80",
  rightSoft: "rgba(74,222,128,0.10)",
  rightBorder: "rgba(74,222,128,0.25)",
  purple: "#8B5CF6",
  purpleSoft: "rgba(139,92,246,0.10)",
  purpleBorder: "rgba(139,92,246,0.25)",
  bg: "#0A0A0A",
};

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
    <AbsoluteFill style={{ backgroundColor: "rgba(0,0,0,0.45)" }} />
  </AbsoluteFill>
);

// ── Hashtag pill ──────────────────────────────────────────────────────────────
const HashtagPill: React.FC<{
  text: string;
  variant: "wrong" | "right";
  progress: number;
}> = ({ text, variant, progress }) => {
  const isWrong = variant === "wrong";
  return (
    <div
      style={{
        display: "inline-flex",
        alignItems: "center",
        backgroundColor: isWrong ? COLORS.wrongSoft : COLORS.rightSoft,
        border: `4px solid ${isWrong ? COLORS.wrongBorder : COLORS.rightBorder}`,
        borderRadius: 48,
        padding: "52px 120px",
        opacity: progress,
        transform: `translateY(${interpolate(progress, [0, 1], [60, 0])}px)`,
      }}
    >
      <span
        style={{
          fontSize: 120,
          fontWeight: 800,
          color: isWrong ? COLORS.wrong : COLORS.right,
          letterSpacing: "0.01em",
          fontFamily: "'Inter', sans-serif",
        }}
      >
        {text}
      </span>
    </div>
  );
};

// ── Icon box ──────────────────────────────────────────────────────────────────
const IconBox: React.FC<{
  color: string;
  softColor: string;
  borderColor: string;
  children: React.ReactNode;
}> = ({ color, softColor, borderColor, children }) => (
  <div
    style={{
      width: 260,
      height: 260,
      borderRadius: 64,
      backgroundColor: softColor,
      border: `4px solid ${borderColor}`,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      flexShrink: 0,
    }}
  >
    {children}
  </div>
);

// ── MAIN SCENE ────────────────────────────────────────────────────────────────
const MainScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const local = (start: number, extra = 0) => Math.max(0, frame - start - extra);

  // ── Segment 1: frames 0–100
  // Fades in at start, holds — no fade out
  const seg1Opacity = interpolate(frame, [0, 8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const s1Pills1 = spring({ frame: local(0, 2),  fps: f, config: { damping: 200 } });
  const s1Pills2 = spring({ frame: local(0, 18), fps: f, config: { damping: 200 } });
  const s1Pills3 = spring({ frame: local(0, 34), fps: f, config: { damping: 200 } });
  const s1Icon   = spring({ frame: local(0, 52), fps: f, config: { damping: 200 } });

  // ── Segment 2: frames 101–227
  // Fades in at 101, holds — no fade out, seg 4 fades in on top
  const seg2Opacity = interpolate(frame, [101, 112], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const s2Pills1 = spring({ frame: local(101, 2),  fps: f, config: { damping: 200 } });
  const s2Pills2 = spring({ frame: local(101, 18), fps: f, config: { damping: 200 } });
  const s2Pills3 = spring({ frame: local(101, 34), fps: f, config: { damping: 200 } });
  const s2Icon   = spring({ frame: local(101, 52), fps: f, config: { damping: 200 } });

  // ── Segment 4: frames 228–321 — NO FADE OUT, freezes on last frame
  const seg4Opacity = interpolate(frame, [228, 240], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const s4Line1 = spring({ frame: local(228, 2),  fps: f, config: { damping: 200 } });
  const s4Line2 = spring({ frame: local(228, 24), fps: f, config: { damping: 200 } });

  // ── Layer visibility
  const showSeg1 = frame < 101 ? seg1Opacity : 0;
  const showSeg2 = frame >= 101 && frame < 228 ? seg2Opacity : 0;
  const showSeg4 = frame >= 228 ? seg4Opacity : 0;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      {/* ══════════════════════════════════════════════
          SEGMENT 1 — Wrong hashtags
          ══════════════════════════════════════════════ */}
      <AbsoluteFill
        style={{
          opacity: showSeg1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: 52, alignItems: "center" }}>
          <HashtagPill text="#marketing"   variant="wrong" progress={s1Pills1} />
          <HashtagPill text="#socialmedia" variant="wrong" progress={s1Pills2} />
          <HashtagPill text="#business"    variant="wrong" progress={s1Pills3} />
        </div>

        {/* Big X */}
        <div
          style={{
            marginTop: 120,
            opacity: s1Icon,
            transform: `scale(${interpolate(s1Icon, [0, 1], [0.3, 1])}) rotate(${interpolate(s1Icon, [0, 1], [-40, 0])}deg)`,
          }}
        >
          <svg width="300" height="300" viewBox="0 0 24 24" fill="none">
            <circle cx="12" cy="12" r="11" fill={COLORS.wrongSoft} stroke={COLORS.wrongBorder} strokeWidth="1" />
            <line x1="7.5" y1="7.5" x2="16.5" y2="16.5" stroke={COLORS.wrong} strokeWidth="2" strokeLinecap="round" />
            <line x1="16.5" y1="7.5" x2="7.5" y2="16.5" stroke={COLORS.wrong} strokeWidth="2" strokeLinecap="round" />
          </svg>
        </div>
      </AbsoluteFill>

      {/* ══════════════════════════════════════════════
          SEGMENT 2 — Right hashtags
          ══════════════════════════════════════════════ */}
      <AbsoluteFill
        style={{
          opacity: showSeg2,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: 52, alignItems: "center" }}>
          <HashtagPill text="#contentmarketing" variant="right" progress={s2Pills1} />
          <HashtagPill text="#growthhacking"    variant="right" progress={s2Pills2} />
          <HashtagPill text="#inboundmarketing" variant="right" progress={s2Pills3} />
        </div>

        {/* Big checkmark */}
        <div
          style={{
            marginTop: 120,
            opacity: s2Icon,
            transform: `scale(${interpolate(s2Icon, [0, 1], [0.3, 1])})`,
          }}
        >
          <svg width="300" height="300" viewBox="0 0 24 24" fill="none">
            <circle cx="12" cy="12" r="11" fill={COLORS.rightSoft} stroke={COLORS.rightBorder} strokeWidth="1" />
            <polyline
              points="7,12.5 10.5,16 17,8.5"
              stroke={COLORS.right}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
          </svg>
        </div>
      </AbsoluteFill>

      {/* ══════════════════════════════════════════════
          SEGMENT 4 — What to post / What to analyze
          NO FADE OUT — freezes on last frame
          ══════════════════════════════════════════════ */}
      <AbsoluteFill
        style={{
          opacity: showSeg4,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Row 1 — Post */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 80,
            marginBottom: 80,
            opacity: s4Line1,
            transform: `translateX(${interpolate(s4Line1, [0, 1], [-120, 0])}px)`,
          }}
        >
          <IconBox
            color={COLORS.accent}
            softColor={COLORS.accentSoft}
            borderColor="rgba(255,107,53,0.35)"
          >
            <svg
              width="130"
              height="130"
              viewBox="0 0 24 24"
              fill="none"
              stroke={COLORS.accent}
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M12 20h9" />
              <path d="M16.5 3.5a2.121 2.121 0 013 3L7 19l-4 1 1-4L16.5 3.5z" />
            </svg>
          </IconBox>
          <span
            style={{
              fontSize: 160,
              fontWeight: 800,
              color: COLORS.accent,
              letterSpacing: "-0.02em",
            }}
          >
            What to post
          </span>
        </div>

        {/* Connector line */}
        <div
          style={{
            width: 4,
            height: 100,
            backgroundColor: "rgba(255,255,255,0.08)",
            marginBottom: 80,
            opacity: s4Line1,
          }}
        />

        {/* Row 2 — Analyze */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 80,
            opacity: s4Line2,
            transform: `translateX(${interpolate(s4Line2, [0, 1], [120, 0])}px)`,
          }}
        >
          <IconBox
            color={COLORS.purple}
            softColor={COLORS.purpleSoft}
            borderColor={COLORS.purpleBorder}
          >
            <svg
              width="130"
              height="130"
              viewBox="0 0 24 24"
              fill="none"
              stroke={COLORS.purple}
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="18" y1="20" x2="18" y2="10" />
              <line x1="12" y1="20" x2="12" y2="4" />
              <line x1="6"  y1="20" x2="6"  y2="14" />
            </svg>
          </IconBox>
          <span
            style={{
              fontSize: 160,
              fontWeight: 800,
              color: COLORS.purple,
              letterSpacing: "-0.02em",
            }}
          >
            What to analyze
          </span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ── MAIN COMPOSITION ──────────────────────────────────────────────────────────
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={321}>
        <MainScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
